"use client";
import { FormEvent, useEffect, useState } from "react";
import { defaultContent, type SiteContent } from "../../lib/site-types";
export default function Contact(){const [content,setContent]=useState<SiteContent>(defaultContent),[sent,setSent]=useState(false);useEffect(()=>{fetch("/api/content").then(r=>r.json()).then(setContent);},[]);function submit(e:FormEvent){e.preventDefault();setSent(true);}return <main className="orderPage" dir="rtl"><a className="back" href="/">← بازگشت به سایت</a><section className="orderBox contactPage"><div><small>رایامهر</small><h1>تماس با ما</h1><p>برای انتخاب پکیج مناسب یا دریافت راهنمایی، با ما در ارتباط باشید.</p><p><b>تماس:</b> {content.phone}</p><p><b>اینستاگرام:</b> @{content.instagram}</p><p><b>واتساپ:</b> {content.whatsapp}</p></div><form onSubmit={submit}><label>نام شما<input required/></label><label>شماره تماس<input required inputMode="tel"/></label><label className="wide">پیام شما<textarea required/></label><button>ارسال پیام</button>{sent&&<p className="orderMessage">پیام شما ثبت شد. به‌زودی پاسخ می‌دهیم.</p>}</form></section></main>}
